<script>
  import { splitObject } from '@splendidlabz/utils'
  import { init } from '../../../utils'
  import Icon from '../../Icon/Icon.svelte'
  import {
    DISCLOSURE_TRIGGER_OPT_KEYS,
    disclosureTrigger,
  } from './disclosure.svelte.js'

  let {
    show = $bindable(false),
    ref = $bindable(null),
    class: klass = '',
    componentName = 'DisclosureTrigger',
    icon = 'tabler:menu',
    iconClass,
    'aria-haspopup': ariaHasPopup = 'dialog',
    target,
    onopen = null,
    onclose = null,
    children,
    ...remainingProps
  } = $props()

  const triggerSplit = $derived(
    splitObject(remainingProps, DISCLOSURE_TRIGGER_OPT_KEYS),
  )
  const triggerOpts = $derived(triggerSplit.picked)
  const eventSplit = $derived(
    splitObject(triggerSplit.omitted, [
      'onbeforeopen',
      'onbeforeclose',
      'onbeforetoggle',
      'ontoggle',
    ]),
  )
  const eventOpts = $derived(eventSplit.picked)
  const final = $derived(eventSplit.omitted)

  init(() => {
    if (!target)
      throw new Error(`${componentName} must contain a target property`)
  })

  function handleOpen(data) {
    show = true
    if (onopen) onopen(data)
  }

  function handleClose(data) {
    show = false
    if (onclose) onclose(data)
  }
</script>

<button
  {...final}
  class="button disclosure-trigger {klass}"
  aria-haspopup={ariaHasPopup}
  data-show={show}
  {target}
  use:disclosureTrigger={{
    state: { show },
    options: {
      ...triggerOpts,
      ...eventOpts,
      onopen: handleOpen,
      onclose: handleClose,
    },
  }}
>
  {#if children}
    {@render children()}
  {:else if icon}
    <Icon class={iconClass} {icon} />
  {/if}
</button>
